export const movieTrailers = mcuMoviesCatalog.reduce((acc, movie) => {
  if (movie.trailerId) {
    acc[movie.title] = movie.trailerId;
  }
  return acc;
}, {});

export default { moviePosters, characterMovieTimeline, movieEvents, mcuMoviesCatalog, movieTrailers };


